SELECT tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (SELECT CAST([], 'Array(Tuple(String, String))') AS tags, grid.timestamp AS timestamp, toFloat64(1) AS value FROM (SELECT arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range({start_ms:Int64}, {end_ms:Int64} + {step_ms:Int64}, {step_ms:Int64}))) AS timestamp) AS grid LEFT JOIN (SELECT eval_ts AS timestamp, sum(length(window_series)) AS sample_count FROM (SELECT source.tags AS tags, grid.eval_ts AS eval_ts, arrayFilter(point -> tupleElement(point, 1) <= grid.eval_ts - toIntervalMillisecond(0) AND tupleElement(point, 1) >= grid.eval_ts - toIntervalMillisecond(300000), source.time_series) AS window_series FROM (SELECT arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range(1700000000000, 1700000300000 + 1, 60000))) AS eval_ts) AS grid CROSS JOIN (
    SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (
        SELECT series.tags AS tags, d.timestamp AS timestamp, d.value AS value FROM timeSeriesData(`observability`.`prometheus`) AS d INNER JOIN (
            SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {absent_window_child_range_matrix_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({absent_window_child_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({absent_window_child_required_end_ms:Int64})
        ) AS series ON d.id = series.id WHERE d.timestamp >= fromUnixTimestamp64Milli({absent_window_child_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({absent_window_child_required_end_ms:Int64}) AND reinterpretAsUInt64(d.value) != 9218868437227405314 AND d.id IN (SELECT id FROM (
            SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {absent_window_child_range_matrix_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({absent_window_child_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({absent_window_child_required_end_ms:Int64})
        ))
    ) GROUP BY tags
) AS source) AS absent_windows GROUP BY eval_ts) AS present ON present.timestamp = grid.timestamp WHERE ifNull(present.sample_count, 0) = 0 ORDER BY timestamp) AS missing_steps GROUP BY tags HAVING length(time_series) > 0
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
